// The dataset: 12 bass-heavy funk/pop/soul albums from the 70s and 80s.
// 'key' is our own ID that links the graph (MusicBrainz) and the text (Wikipedia).
// 'wiki' is the exact English Wikipedia article title (search hit wrong pages).
const albums = [
  ['Michael Jackson', 'Off the Wall', 'Off the Wall'],
  ['Michael Jackson', 'Thriller', 'Thriller (album)'],
  ['The Brothers Johnson', 'Light Up the Night', 'Light Up the Night (The Brothers Johnson album)'],
  ['Quincy Jones', 'The Dude', 'The Dude (Quincy Jones album)'],
  ['Stevie Wonder', 'Songs in the Key of Life', 'Songs in the Key of Life'],
  ['Chic', 'Risqué', 'Risqué (album)'],
  ['Earth, Wind & Fire', 'I Am', 'I Am (Earth, Wind & Fire album)'],
  ['Level 42', 'World Machine', 'World Machine'],
  ['Prince and the Revolution', 'Purple Rain', 'Purple Rain (album)'],
  ['Toto', 'Toto IV', 'Toto IV'],
  ['George Benson', 'Give Me the Night', 'Give Me the Night (album)'],
  ['Marcus Miller', "The Sun Don't Lie", "The Sun Don't Lie"],
];
return albums.map(([artist, title, wiki]) => ({ json: { artist, title, wiki, key: `${artist} - ${title}` } }));

// Normalize instrument names from MusicBrainz
const norm = (s) => {
  s = s.toLowerCase();
  if (/bass guitar|^bass$|double bass|contrabass/.test(s)) return 'bass';
  if (/guitar/.test(s)) return 'guitar';
  if (/drum|percussion|conga|tambourine/.test(s)) return 'drums/percussion';
  if (/synth|keyboard|piano|rhodes|organ|clavinet/.test(s)) return 'keys';
  if (/vocal/.test(s)) return 'vocals';
  if (/trumpet|flugelhorn|trombone|horn/.test(s)) return 'horns';
  if (/sax/.test(s)) return 'saxophone';
  return s;
};

const sources = $('Album List').all();
const rows = [];
$input.all().forEach((item, idx) => {
  const r = item.json;
  const src = sources[idx].json;
  const mainArtist = r['artist-credit']?.[0]?.artist;

  const album = {
    mbid: r.id,
    key: src.key,
    title: src.title,
    year: r.date ? parseInt(r.date.slice(0, 4)) : null,
    artist: mainArtist ? { mbid: mainArtist.id, name: mainArtist.name } : null,
    label: r['label-info']?.[0]?.label?.name ?? null,
    genres: (r.genres || []).map(g => g.name),
  };

  // Collect credits from release and track level, deduplicated
  const credits = new Map();
  const add = (rel) => {
    if (rel['target-type'] !== 'artist' || !rel.artist) return;
    const a = { mbid: rel.artist.id, name: rel.artist.name };
    if (rel.type === 'producer') {
      credits.set(`${a.mbid}|producer`, { ...a, role: 'producer', instrument: null });
    } else if (rel.type === 'instrument' || rel.type === 'vocal') {
      const list = rel.attributes?.length ? rel.attributes : [rel.type === 'vocal' ? 'vocals' : 'unknown'];
      for (const ins of list) {
        const i = norm(ins);
        credits.set(`${a.mbid}|played|${i}`, { ...a, role: 'played', instrument: i });
      }
    }
  };
  (r.relations || []).forEach(add);
  for (const m of r.media || [])
    for (const t of m.tracks || [])
      (t.recording?.relations || []).forEach(add);

  rows.push({ album, credits: [...credits.values()] });
});

// One single request/transaction for all albums.
// Parallel requests MERGE'ing the same shared artists (e.g. Quincy Jones) deadlock in Neo4j.
const statement = `
UNWIND $rows AS row
WITH row, row.album AS a
MERGE (al:Album {mbid: a.mbid})
  SET al.title = a.title, al.key = a.key, al.year = a.year
FOREACH (_ IN CASE WHEN a.artist IS NULL THEN [] ELSE [1] END |
  MERGE (ar:Artist {mbid: a.artist.mbid}) SET ar.name = a.artist.name
  MERGE (al)-[:BY]->(ar))
FOREACH (_ IN CASE WHEN a.label IS NULL THEN [] ELSE [1] END |
  MERGE (l:Label {name: a.label}) MERGE (al)-[:ON_LABEL]->(l))
FOREACH (g IN a.genres |
  MERGE (ge:Genre {name: g}) MERGE (al)-[:HAS_GENRE]->(ge))
WITH al, row
UNWIND row.credits AS c
MERGE (p:Artist {mbid: c.mbid}) SET p.name = c.name
FOREACH (_ IN CASE WHEN c.role = 'producer' THEN [1] ELSE [] END |
  MERGE (al)-[:PRODUCED_BY]->(p))
FOREACH (_ IN CASE WHEN c.role = 'played' THEN [1] ELSE [] END |
  MERGE (p)-[:PLAYED_ON {instrument: c.instrument}]->(al))`;

return [{ json: {
  summary: rows.map(r => `${r.album.title}: ${r.credits.length} credits`),
  statement,
  parameters: { rows },
}}];

// Chunk Wikipedia articles by their own section structure.
// Sections that duplicate the graph or add noise are skipped.
const SKIP = /^(references|external links|track listing|personnel|credits|charts|certifications|notes|see also|further reading|release history|accolades|sales)/i;
const MAX = 1000, STEP = 900; // 100 chars overlap for long sections

const sources = $('Album List').all();
const out = [];
$input.all().forEach((item, idx) => {
  const src = sources[idx].json;
  const page = Object.values(item.json.query?.pages || {})[0];
  if (!page?.extract) return;

  // split on '== Heading ==' lines -> [intro, '==', 'Heading', body, '===', 'Sub', body, ...]
  const parts = page.extract.split(/\n(={2,})\s*(.+?)\s*\1\n/);
  const sections = [{ level: 2, title: 'Introduction', body: parts[0] }];
  for (let i = 1; i < parts.length; i += 3)
    sections.push({ level: parts[i].length, title: parts[i + 1], body: parts[i + 2] || '' });

  let skipping = false, n = 0;
  for (const s of sections) {
    if (s.level === 2) skipping = SKIP.test(s.title);
    if (skipping) continue;
    const text = s.body.trim();
    if (text.length < 100) continue;
    for (let i = 0; i < text.length; i += STEP) {
      out.push({ json: {
        id: `${src.key}#${n++}`,
        key: src.key,
        album: src.title,
        artist: src.artist,
        section: s.title,
        source: page.fullurl,
        // prefix gives each chunk context about which album it belongs to
        text: `${src.artist} - ${src.title} (${s.title}): ${text.slice(i, i + MAX)}`,
      }});
    }
  }
});
return out;

