// Combine every chunk + its embedding into one list,
// so Neo4j gets a single request (no parallel writes -> no deadlocks).
const chunks = $('Chunk').all();
const rows = $input.all().map((item, i) => ({
  ...chunks[i].json,
  embedding: item.json.embeddings[0],
}));
return [{ json: { chunk_count: rows.length, rows } }];
